    DesignerPolicyPanel(ResearchDesignerWorkspaceScreen host){super(Component.literal(DesignerText.tr("properties.research_properties_simulation")));this.host=host;
        scenario=host.simulationState();nodeId=host.editingPrimary();branchId=host.editingBranch();
        inputs.put("target",nodeId==null?"":ResearchDesignerStructure.node(project(),nodeId).blueprintId().orElse(""));
    }
    private ResearchDesignerProject project(){return host.editingSession().project();}
    private ResearchDesignerCapture capture(){return host.editingCapture().orElseThrow(()->new IllegalArgumentException(DesignerText.tr("properties.capture_a_server_tree_to_resolve_dependency_facts_first")));}
    private Button button(int y,String label,Runnable action){return button(x,y,w,label,action);}
    private Button button(int px,int y,int width,String label,Runnable action){return addRenderableWidget(Button.builder(Component.literal(label),b->{try{if(busy&&!label.equals(DesignerText.tr("properties.back"))&&!label.equals(DesignerText.tr("properties.close")))return;action.run();}catch(RuntimeException e){error=Objects.toString(e.getMessage(),DesignerText.tr("properties.invalid_input"));minecraft.getNarrator().sayNow(Component.literal(error));}}).bounds(px,y,width,20).build());}
    private void show(Page value){if(pendingWork!=null)pendingWork.cancel();token++;busy=false;page=value;offset=0;error="";rebuildWidgets();}
    private String get(String id,String fallback){return inputs.getOrDefault(id,fallback);}
    private EditBox field(int y,String id,String fallback,String label){var box=addRenderableWidget(new EditBox(font,x,y,w,20,Component.literal(label)));box.setMaxLength(32767);box.setValue(get(id,fallback));box.setResponder(v->inputs.put(id,v));box.setTooltip(Tooltip.create(Component.literal(label)));return box;}
    private int number(String id,String fallback,int maximum){try{int n=new java.math.BigDecimal(get(id,fallback)).intValueExact();if(n<0||n>maximum)throw new IllegalArgumentException();return n;}catch(RuntimeException e){throw new IllegalArgumentException(DesignerText.tr("properties.use_a_whole_number_from_0_to")+maximum+" for "+id);}}
    private void cycle(int y,String key,List<String> options,String fallback,String label){String current=get(key,fallback);button(y,label+": "+current,()->{inputs.put(key,options.get((options.indexOf(current)+1)%options.size()));rebuildWidgets();});}
    private void list(List<String> values,java.util.function.IntConsumer action,int top){int rows=Math.max(1,(height-top-78)/22);offset=Math.min(offset,Math.max(0,((values.size()-1)/rows)*rows));for(int i=0;i<rows&&offset+i<values.size();i++){int index=offset+i;String label=values.get(index);button(top+i*22,font.plainSubstrByWidth(label,w-12),()->action.accept(index)).setTooltip(Tooltip.create(Component.literal(label)));}
        button(x,height-70,72,DesignerText.tr("properties.previous"),()->{offset-=rows;rebuildWidgets();}).active=offset>0;button(x+76,height-70,72,DesignerText.tr("properties.next"),()->{offset+=rows;rebuildWidgets();}).active=offset+rows<values.size();}
    private void review(ResearchDesignerStructure.Proposal value){proposal=value;previous=page;show(Page.REVIEW);}
    private <T> void work(java.util.concurrent.Callable<T> task,java.util.function.Consumer<T> success){if(pendingWork!=null)pendingWork.cancel();int request=++token;busy=true;error="";rebuildWidgets();pendingWork=DesignerClientWork.submit(task,answer->{if(request!=token||!host.isDetail(this))return;busy=false;success.accept(answer);rebuildWidgets();},e->{if(request!=token||!host.isDetail(this))return;busy=false;error=Objects.toString(e.getMessage(),DesignerText.tr("properties.preview_unavailable"));rebuildWidgets();});}
